#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Render the zkPassport digest bind proof as Solidity constants.

Reads valid_proof.hex, valid_public_inputs.json and valid_committed_inputs.hex from this
directory, as upstream's generate-fixtures.ts wrote them, and writes ZkPassportDigestBindFixture.sol
next to them. Tests may read files only under test/fixtures/kats and out, so the fork tests take the
proof from these constants instead of reading the files. Run it from anywhere:

    python3 test/fixtures/zkpassport-digest/generate.py

The output is deterministic, so running it again on unchanged files leaves the .sol file
unchanged, which `git diff --exit-code` confirms. The script also refuses committed inputs that do
not carry the digest's rendering, so the constants always bind the digest they name.
"""

import json
import pathlib

HERE = pathlib.Path(__file__).resolve().parent
HEX_CHARS_PER_LINE = 96
FIRST_PART_HEX_CHARS = 48
DIGEST = '0xb6566bf299a764e0c0a1f4ca4805b7b977ea3a018675b1596e7363854202ec53'


def read_hex(name):
    text = (HERE / name).read_text().strip()
    if text.startswith('0x'):
        text = text[2:]
    bytes.fromhex(text)  # refuses anything that is not whole bytes of hexadecimal
    return text.lower()


def hex_literal(head, text, indent):
    """Split a hex literal into parts Solidity concatenates. The first part shares the declaration's line, as
    forge fmt places it, and is short enough to keep that line within 120 columns."""
    parts = [text[:FIRST_PART_HEX_CHARS]]
    parts += [text[i:i + HEX_CHARS_PER_LINE] for i in range(FIRST_PART_HEX_CHARS, len(text), HEX_CHARS_PER_LINE)]
    return '\n'.join([f"{head} hex'{parts[0]}'"] + [f"{indent}hex'{part}'" for part in parts[1:]])


def main():
    proof = read_hex('valid_proof.hex')
    committed = read_hex('valid_committed_inputs.hex')
    assert DIGEST.encode().hex() in committed, 'the committed inputs do not carry the digest rendering'
    inputs = json.loads((HERE / 'valid_public_inputs.json').read_text())['inputs']
    for word in inputs:
        assert len(word) == 66 and word.startswith('0x'), word
        bytes.fromhex(word[2:])

    lines = [
        '// SPDX-License-Identifier: GPL-3.0-or-later',
        'pragma solidity 0.8.30;',
        '',
        '// Generated by test/fixtures/zkpassport-digest/generate.py. Do not edit by hand: edit the data files and run',
        '// it again.',
        '//',
        '// The data was produced with src/ts/scripts/generate-fixtures.ts from zkpassport/circuits at commit',
        '// 9682885268d631f1331513be88ba5646961f77f0, Copyright 2025 ZKPassport, licensed under the Apache License,',
        '// Version 2.0, with the bind custom data changed to the digest below. See NOTICE and LICENSE in this',
        '// directory. The values are copied unchanged from the generator\'s output.',
        '',
        '/// @notice A zkPassport 0.21.1 bind proof whose custom data is the zkPassport method\'s rendering of one fixed',
        '///         digest. The outer proof wraps five subproofs, the last two a disclosure and a bind. It was made for',
        '///         upstream\'s fake test passport, whose certificate root no live registry holds.',
        'abstract contract ZkPassportDigestBindFixture {',
        '  /// @notice The digest the proof binds, rendered in the custom data as 0x and sixty four lowercase hex digits.',
        f'  bytes32 internal constant _ZK_DIGEST_BIND_DIGEST = {DIGEST};',
        '',
        f'  /// @notice The outer proof, {len(proof) // 2} bytes.',
        hex_literal('  bytes internal constant _ZK_DIGEST_BIND_PROOF =', proof, '    ') + ';',
        '',
        f'  /// @notice The preimages of the proof\'s parameter commitments, {len(committed) // 2} bytes.',
        hex_literal('  bytes internal constant _ZK_DIGEST_BIND_COMMITTED_INPUTS =', committed, '    ') + ';',
        '',
    ]
    for index, word in enumerate(inputs):
        lines.append(f'  /// @notice Public input {index} of {len(inputs)}.')
        lines.append(f'  bytes32 internal constant _ZK_DIGEST_BIND_PUBLIC_INPUT_{index} =')
        lines.append(f'    {word.lower()};')
        lines.append('')
    lines += [
        '  /// @notice The public inputs, in the order the proof commits to them.',
        '  /// @return _inputs The public inputs.',
        '  function _zkDigestBindPublicInputs() internal pure returns (bytes32[] memory _inputs) {',
        f'    _inputs = new bytes32[]({len(inputs)});',
    ]
    for index in range(len(inputs)):
        lines.append(f'    _inputs[{index}] = _ZK_DIGEST_BIND_PUBLIC_INPUT_{index};')
    lines += ['  }', '}', '']
    (HERE / 'ZkPassportDigestBindFixture.sol').write_text('\n'.join(lines))


if __name__ == '__main__':
    main()
